/** Each islet's outline in local metres (e, n), counter-clockwise seen from above. */
export function isletOutlines(): { name: string; height: number; ring: [number, number][] }[] {
  return ISLETS.map((i) => {
    let ring = i.ring.map(([lat, lon]) => {
      const p = DART_PROJECTION.toLocal(lat, lon);
      return [p.e, p.n] as [number, number];
    });
    let a = 0;
    for (let k = 0; k < ring.length; k++) {
      const [e0, n0] = ring[k]!;
      const [e1, n1] = ring[(k + 1) % ring.length]!;
      a += e0 * n1 - e1 * n0;
    }
    if (a < 0) ring = ring.reverse();
    return { name: i.name, height: i.height, ring };
  });
}

/** The islets as solid outlines for the boats (src/sim/race/setup.ts raceStructures): fixed rock. */
export function isletStructures(): { name: string; floating: false; poly: [number, number][] }[] {
  return isletOutlines().map((o) => ({ name: `the ${o.name}`, floating: false as const, poly: o.ring }));
}
